return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg_BG','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Многоезичен WordPress, по една публикация на език: свързани преводи на публикации, страници, категории, медиен текст, джаджи и заглавие на сайта, с импортирани вашите стари преводи от Tranzly.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Доставчици на AI','The makers of ChatGPT. A good all-rounder.'=>'Създателите на ChatGPT. Добър универсален избор.','The makers of Claude. Strong at writing and careful reasoning.'=>'Създателите на Claude. Силни в писането и внимателното мислене.','Google\'s Gemini models. Fast and inexpensive.'=>'Моделите Gemini на Google. Бързи и евтини.','A European AI company with fast, inexpensive models.'=>'Европейска AI компания с бързи и евтини модели.','Low-cost models that are good at writing and code.'=>'Нискобюджетни модели, които се справят добре с писане и код.','One key for models from many different providers.'=>'Един ключ за модели от множество различни доставчици.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Всяка услуга, която работи като API на OpenAI, включително модел, който се изпълнява на вашия собствен компютър или сървър.','General (used when nothing more specific is set)'=>'Общи (използва се, когато няма зададено по-специфично)','Writing and rewriting'=>'Писане и пренаписване','Translation'=>'Превод','Code and CSS'=>'Код и CSS','Sorry, you are not allowed to access this page.'=>'За съжаление, нямате достъп до тази страница.','These settings are shared by every plugin that uses them: %s.'=>'Тези настройки се споделят от всеки плъгин, който ги използва: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Вашите ключове са криптирани в базата данни на този сайт и се изпращат само до избрания от вас доставчик — никога до нас.','Step 1 of 2: choose an AI provider'=>'Стъпка 1 от 2: изберете доставчик на ИИ','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Вие използвате собствен ключ, така че плащате директно на доставчика за това, което използвате. Не сте сигурни? Всеки от тези варианти е подходящ; можете да добавите още по-късно.','Next'=>'Напред','Step 2 of 2: connect %s'=>'Стъпка 2 от 2: свързване на %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Въведете адреса на вашата съвместима с OpenAI услуга, завършващ на /v1. Ключ е необходим само ако услугата изисква такъв.','Open %s and sign in (or create a free account).'=>'Отворете %s и влезте в профила си (или създайте безплатен акаунт).','the %s API keys page'=>'страницата с API ключове на %s','Create a new key and copy it.'=>'Създайте нов ключ и го копирайте.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Поставете го по-долу и натиснете „Запази и тествай“. Ние изпращаме една малка заявка, за да проверим дали работи.','Most providers need a little credit on the account before a key works: %s.'=>'Повечето доставчици изискват малко кредит по сметката, преди ключът да започне да работи: %s.','add credit'=>'добавяне на кредит','← Choose a different provider'=>'← Изберете друг доставчик','Address'=>'Адрес','Saved key ends in …%s — paste a new one to replace it'=>'Запазеният ключ завършва на …%s — поставете нов, за да го замените','Key (optional)'=>'Ключ (по избор)','API key'=>'API ключ','Save and test'=>'Запази и тествай','Providers'=>'Доставчици','Provider'=>'Доставчик','Status'=>'Статус','Key'=>'Ключ','Get a key'=>'Вземете ключ','Test'=>'Тест','Remove'=>'Премахване','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Запазено с по-нова версия на плъгина: актуализирайте този плъгин или въведете ключа отново.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Запазеният ключ вече не може да бъде отворен (ключовете за сигурност на сайта са променени). Въведете го отново.','Not connected'=>'Няма връзка','Connected — last test passed %s'=>'Свързан — последният тест е успешен %s','Last test failed: %s'=>'Последният тест неуспешен: %s','Connected — not tested yet'=>'Свързан — все още не е тестван','Which model to use'=>'Кой модел да се използва','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ отбелязва нашата препоръка за тази задача. Списъкът включва всеки модел, който вашият ключ може да използва, зареден на живо от доставчика.','— Recommended for the provider —'=>'— Препоръчително за доставчика —','Save models'=>'Запазване на моделите','Refresh the model lists from the providers'=>'Обновяване на списъците с модели от доставчиците','best quality'=>'най-високо качество','lowest cost'=>'най-ниска цена','fastest'=>'най-бързи','Add a model yourself'=>'Добавете модел сами','A model came out today? Paste its exact name to use it straight away.'=>'Излезе нов модел днес? Поставете точното му име, за да го използвате веднага.','Model name'=>'Име на модел','Add model'=>'Добавяне на модел','Recommended models list'=>'Список с препоръчани модели','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Списъкът с препоръчани модели не можа да бъде потвърден, затова не се показват препоръки. Преинсталирайте плъгина или включете ежедневните актуализации по-долу.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Използваният списък е публикуван на %s. Всяка актуализация на плъгин предоставя нов такъв.','Also check Zinn Digital® once a day for an updated list.'=>'Също така проверявайте Zinn Digital® веднъж дневно за актуализиран списък.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Изпраща се само обикновена заявка за изтегляне: без ключ, без адрес на сайт, нищо за вашето съдържание. Списъкът е подписан и списък, който не издържи проверката на подписа, се игнорира.','Last checked %1$s: %2$s.'=>'Последна проверка на %1$s: %2$s.','Save, and check now if turned on'=>'Запазете и проверете сега, ако е включено','a newer list was installed'=>'инсталиран е по-нов списък','already up to date'=>'вече е актуално','the download failed the signature check and was ignored'=>'изтеглянето неуспешно преминали проверките за подпис и беше игнорирано','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® не беше достъпен; текущият списък остава в употреба','turned off'=>'изключено','Open'=>'Отваряне','Check their status page'=>'Проверете тяхната страница за състоянието','Open your billing page'=>'Отворете страницата си за таксуване','Open your API keys page'=>'Отворете страницата си за API ключове','Open the AI settings'=>'Отворете настройките за AI','Sorry, you are not allowed to do that.'=>'За съжаление, нямате разрешение да направите това.','Unknown provider.'=>'Неизвестен доставчик.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Въведете адреса на вашата услуга, например http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Това не прилича на API ключ. Копирайте го отново, без интервали.','Paste your API key first.'=>'Първо поставете своя API ключ.','Key removed.'=>'Ключът е премахнат.','Models saved.'=>'Моделите са запазени.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Въведете точното име на модела, например както е записано в документацията на доставчика.','Added %s. Choose it under "Which model to use".'=>'Добавено %s. Изберете го в „Кой модел да се използва“.','Model removed.'=>'Моделът е премахнат.','Daily updates are off. The list that came with the plugin is used.'=>'Ежедневните актуализации са изключени. Използва се списъкът, който е дошъл с плъгина.','Checked: %s.'=>'Маркирани: %s.','Model lists refreshed.'=>'Списъците с модели са обновени.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Вашият AI ключ е бил запазен от по-нова версия на една от вашите приставки. Актуализирайте тази приставка или въведете ключа отново в AI настройките.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Вашият запазен AI ключ вече не може да бъде отворен (ключовете за сигурност на сайта са се променили). Въведете го отново в настройките за AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Изкуственият интелект все още не е настроен. Добавете ключ за AI доставчик в настройките за AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Няма избран модел за тази задача. Изберете такъв в настройките за AI.','That AI provider is not supported by this version of the plugin.'=>'Този доставчик на изкуствен интелект не се поддържа от тази версия на плъгина.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Този сайт не можа да осъществи връзка с вашата AI услуга. Проверете дали тя работи и дали нейният адрес е достъпен от вашия уеб сървър (услуга на вашия собствен компютър не е достъпна от хостван сайт).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Този сайт не можа да осъществи връзка с %s. Проверете тяхната страница за състоянието; ако те работят, вашият хост може да блокира изходящи връзки или адресът е грешен.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s съобщава, че в профила ви няма наличен кредит или квота. Добавете кредит или увеличете лимита в профила си при тях и опитайте отново.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s не прие вашия ключ. Възможно е да е сгрешен, отменен или с изтекъл срок на валидност. Създайте нов ключ и го поставете тук.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s отхвърли тази заявка за вашия ключ. Ключът може да няма достъп до този модел или функционалност, или вашият акаунт се нуждае от верификация.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Моделът „%1$s“ не е наличен от %2$s за вашия ключ. Изберете друг модел в настройките за изкуствен интелект.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Вашият план %2$s не включва модела "%1$s". Изберете друг модел в настройките за AI или надстройте своя план с тях.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ограничава скоростта, с която вашият ключ може да изпраща заявки. Изчакайте минута и опитайте отново или увеличете лимита на заявките при тях.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s има проблеми в момента (прекъсване или претоварване от тяхна страна). Всичко с вашите настройки е наред. Опитайте отново скоро.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Заявката към изкуствения интелект се провали по неизяснена причина. Опитайте отново; ако проблемът продължава, свържете се с поддръжката с данните по-долу.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Доставчикът на изкуствен интелект отговори във формат, който тази приставка не може да разчете. Опитайте отново; ако проблемът продължава, изберете друг модел или се свържете с поддръжката.','Custom (OpenAI-compatible)'=>'Потребителски (съвместим с OpenAI)','Save a key for this provider first.'=>'Първо запишете ключ за този доставчик.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Вашият ключ работи, но доставчикът не посочва текстов модел за него. Добавете модел сами по-долу.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Свързано. %1$s отговори чрез %2$s. Вашите функции с изкуствен интелект са готови за употреба.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Вашата потребителска роля няма право да използва изкуствен интелект в този сайт. Обърнете се към администратор.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Този сайт е достигнал месечния си лимит за разходи за AI. Администратор може да го увеличи в настройките за AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Този сайт е достигнал месечния си лимит за AI заявки. Администратор може да го увеличи в настройките за AI.','Usage and cost'=>'Използване и разходи','The log, limits and role permissions apply to AI used through: %s.'=>'Дневникът, лимитите и разрешенията за ролите се важат за ИИ, използван чрез: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Разходите са приблизителни, изчислени на базата на публикувани цени; модел без известна цена се брои за нула.','This month: %1$s requests, about %2$s.'=>'Този месец: %1$s заявки, около %2$s.','When'=>'Кога','Who'=>'Кой','Used for'=>'Използва се за','Model'=>'Модел','Tokens in / out'=>'Токени вх. / изх.','About'=>'Относно','Result'=>'Резултат','No AI requests have been made yet.'=>'Все още няма направени заявки към AI.','Done'=>'Готово','Limits and permissions'=>'Лимити и разрешения','Monthly spending limit (US dollars)'=>'Месечен лимит на разходите (US щатски долари)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Оставете празно за без лимит. Изкуственият интелект спира за остатъка от месеца, щом приблизителната цена достигне това ниво.','Monthly request limit'=>'Месечен лимит на заявките','Leave empty for no limit.'=>'Оставете празно за без лимит.','Who may use AI'=>'Кой може да използва ИИ','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Не избирайте нищо, за да позволите на всеки, който може да използва функциите на плъгина, да използва изкуствен интелект. Администраторите винаги могат да го използват.','Save limits and permissions'=>'Запазване на лимити и разрешения','Limits and permissions saved.'=>'Лимитите и правата са запазени.','That language is not one of this site\'s languages.'=>'Този език не е сред езиците на този сайт.','A translation must be the same kind of content as the original.'=>'Преводът трябва да бъде от същия вид съдържание като оригинала.','Choose one of the site\'s other languages.'=>'Изберете един от другите езици на сайта.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Скриптовете на администраторския екран липсват в това копие на плъгина. Преинсталирайте го от пуснат в обращение пакет.','This screen needs JavaScript.'=>'Този екран изисква JavaScript.','Choose a language'=>'Изберете език','Upgrade'=>'Надграждане','Pricing'=>'Ценообразуване','Start Trial'=>'Начало на пробен период','Account'=>'Акаунт','Contact Us'=>'Свържете се с нас','Affiliation'=>'Афилиейт','the kind of softwarePlugin'=>'Плъгин','greetingHey %s,'=>'Здравейте %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Абонирайте се за получаване на имейл известия за актуализации на сигурността и функциите, образователно съдържание и периодични оферти, както и за споделяне на основна информация за средата на WordPress. Това ще ни помогне да направим %s по-съвместим с вашия сайт и да върши по-добре работата, която ви е необходима.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Абонирайте се за получаване на имейл известия за актуализации на сигурността и функциите, образователно съдържание и периодични оферти, както и за споделяне на основна информация за средата на WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ако пропуснете това, няма проблем! %1$s ще продължи да работи перфектно.','Allow & Continue'=>'Разреши и продължи','verbSkip'=>'Пропусни','Skipping, please wait'=>'Пропускане, моля изчакайте','Continue'=>'Продължи','Please wait'=>'Моля, изчакайте','as activating pluginActivating'=>'Активиране','This will allow %s to'=>'Това ще позволи на %s да','Privacy Policy'=>'Политика за поверителност','Terms of Service'=>'Общи условия','License Agreement'=>'Лицензионно споразумение','Have a license key?'=>'Имате ли лицензионен ключ?','Activate License'=>'Активиране на лиценз','View Basic Profile Info'=>'Преглед на основната информация в профила','Your WordPress user\'s: first & last name, and email address'=>'Име, фамилия и имейл адрес на Вашия потребител на WordPress','View Basic Website Info'=>'Преглед на основната уебсайт информация','Homepage URL & title, WP & PHP versions, and site language'=>'URL и заглавие на началната страница, версии на WP и PHP, и език на сайта','View Basic %s Info'=>'Вижте основна информация за %s','Current %s & SDK versions, and if active or uninstalled'=>'Текущи %s и SDK версии, както и дали са активни или деинсталирани','Newsletter'=>'Бюлетин','Updates, announcements, marketing, no spam'=>'Актуализации, съобщения, маркетинг, без спам','View Diagnostic Info'=>'Преглед на диагностична информация','WordPress & PHP versions, site language & title'=>'WordPress и PHP версии, език и заглавие на сайт','View Plugins & Themes List'=>'Преглед на списъка с плъгини и теми','Names, slugs, versions, and if active or not'=>'Имена, идентификатори, версии и дали са активни, или не','optional'=>'по избор','Never miss an important update'=>'Никога не пропускайте важно обновление','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Въведохме тази възможност за избор, за да не пропускате нито една важна актуализация и да ни помогнете да направим %s по-съвместим с Вашия сайт и по-добър в изпълнението на това, което Ви е необходимо.','Thank you for updating to %1$s v%2$s!'=>'Благодарим ви, че актуализирахте до %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Префиксът трябва да се състои от 1 до 8 малки букви или цифри, да започва с буква и да не съвпада с името на плъгина.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'„%s“ не е код на език. Използвайте локал за WordPress, като например fr_FR или de_DE.','List at least one language.'=>'Избройте поне един език.','You are not allowed to translate this item.'=>'Нямате разрешение да превеждате този елемент.','This item already has a version in that language.'=>'Този артикул вече има версия на този език.','That translation engine is not available on this site.'=>'Този механизъм за превод не е наличен в този сайт.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Различните двигатели за език, автоматичният резервен вариант и лимитите на разходите са функции на Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Всякa език трябва да бъде един от езиците на сайта с наличен двигател.','The fallback list may only name available engines.'=>'Резервният списък може да съдържа само налични двигатели.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Месечният лимит е сума в US долари, нула или повече, за наличен механизъм.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Предпочитителата преводи и тон за език са функции на Tranzly Pro. Списъкът с думи за непревеждане е безплатен.','Glossary entries must be grouped by one of the site\'s languages.'=>'Речниците трябва да бъдат грутирани по един от езиците на сайта.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Тонът се задава за всеки език на сайта: стандартна формалност, повече или по-малко, плюс незадължителни инструкции.','The value for %s is not one of the allowed choices.'=>'Стойността за %s не е сред позволените възможности.','The background queue is not available on this site.'=>'Фоновата опашка не е налична в този сайт.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Задачата за превод се изпълнява от името на потребителя, който я стартира, така че той трябва да е влязъл в системата.','There is nothing you are allowed to translate in that selection.'=>'Няма нищо, което ви е разрешено да превеждате в тази селекция.','That item is not part of a translation job.'=>'Този артикул не е част от задача за превод.','You are not allowed to change that translation.'=>'Нямате право да променяте този превод.','This item\'s group already has a %1$s version (#%2$d).'=>'Групата на този артикул вече има %1$s версия (#%2$d).','An item cannot be its own translation.'=>'Един елемент не може да бъде свой собствен превод.','That item is already a translation of something else. Unlink it first.'=>'Този елемент вече е превод на нещо друго. Първо го отвържете.','The translation link could not be saved.'=>'Връзката за превод не можа да бъде запазена.','That text cannot be translated here.'=>'Този текст не може да бъде преведен тук.','That media text cannot be translated here.'=>'Този медиен текст не може да бъде преведен тук.','A translation can be published or kept as a draft.'=>'Един превод може да бъде публикуван или запазен като чернова.','You are not allowed to publish this kind of content.'=>'Нямате разрешение да публикувате такъв тип съдържание.','This item is already written in that language.'=>'Този елемент вече е написан на този език.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Този превод е редактиран от човек (или импортиран), така че е защитен. Отключете го, за да го преведете отново.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Все още няма настроен двигател за превод. Добавете ключ за такъв в Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Този двигател за превод все още не е настроен: първо добавете неговия ключ.','The same text is being translated by another job right now; this item will use that answer.'=>'Същият текст се превежда от друга задача в момента; този елемент ще използва този отговор.','No translation engine could take this item.'=>'Нито един преводачески двигател не успя да приеме този елемент.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Двигателят не върна превод за всяка част от този елемент. Нищо не беше променено.','AI model'=>'AI модел','AI model (%1$s %2$s)'=>'AI модел (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s има проблеми в момента. Опитайте отново след малко или използвайте друга търсачка.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Сайтът ви не можа да осъществи връзка с %s. Проверете дали той може да установява изходящи връзки и опитайте отново.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s не прие вашия API ключ. Проверете ключа в Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Вашият акаунт %s е изчерпал своята квота или баланс. Заредете го с тях или използвайте друг двигател.','%s asked us to slow down. It will be tried again automatically.'=>'%s поиска да забавим темпото. Опитът ще бъде повторен автоматично.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Този текст е твърде дълъг за %s наведнъж. Разделете съдържанието или използвайте друг двигател.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s отказа да преведе това съдържание. Опитайте с друг двигател или го преведете ръчно.','%s does not translate this language. Choose another engine for it.'=>'%s не превежда този език. Изберете друг двигател за него.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Месечният лимит на разходите за %s е достигнат, така че към него не бяха изпратени повече данни. Увеличете лимита в Tranzly → Engines или изчакайте следващия месец.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Преводът с %s неуспешен поради причина, която Tranzly не успя да идентифицира. Подробностите са по-долу.','An engine id must be lowercase letters, digits and hyphens.'=>'Идентификаторът на модул трябва да съдържа само малки букви, цифри и тирета.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Създадено от Neil Lock, главен изпълнителен директор на Zinn Digital® Ltd','Version %s'=>'Версия %s','Tranzly website'=>'Уебсайт Tranzly','Zinn Digital® website'=>'Увеселителен уебсайт на Zinn Digital®','Settings saved.'=>'Настройките са запазени.','See the Pro plans and pricing'=>'Разгледайте плановете и цените на Pro','Languages'=>'Езици','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Първият език е този, на който е написано вашето съдържание. Посетителите превключват с блока за превключване на езици.','(default)'=>'(по подразбиране)','Locale code'=>'Езиков код','For example fr_FR'=>'Например fr_FR','Name (optional)'=>'Име (по избор)','For example Français'=>'Например Français','Add language'=>'Добавяне на език','Front-end output'=>'Външен изходен код','Class name prefix'=>'Префикс на име на клас','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Всяко име на клас, което плъгинът отпечатва на вашите страници, започва с този префикс, така че страниците да не разкриват кой плъгин ги е създал. От 1 до 8 малки букви или цифри, започващи с буква.','Beta updates'=>'Бета актуализации','This site receives beta versions as updates.'=>'Този сайт получава бета версии като актуализации.','This site receives stable versions only.'=>'Този сайт получава само стабилни версии.','Change this on the Account page'=>'Променете това на страницата на акаунта','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Бета версиите се предлагат за лицензирани инсталации на Pro, които са свързани към своя акаунт. След като се свържете, можете да се присъедините от страницата „Акаунт“.','Save settings'=>'Запазване на настройките','First engine that is set up'=>'Първият двигател, който е настроен','Key saved. It is stored encrypted and never shown again.'=>'Ключът е запазен. Той се съхранява в шифрован вид и никога повече няма да бъде показан.','Engine settings saved.'=>'Настройките на двигателя са запазени.','Glossary saved.'=>'Речникът е запазен.','Your keys'=>'Вашите ключове','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly извиква услугите за превод с вашия собствен акаунт. Ключовете се съхраняват криптирани във вашата база данни и се изпращат само до услугата, към която принадлежат. Ключовете за AI моделите се задават в настройките на AI.','%s API key'=>'%s API ключ','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Запазено: %s. Въведете нов ключ, за да го замените, или запазете полето празно, за да го премахнете.','No key saved.'=>'Няма записан ключ.','Azure region (leave empty for a global resource)'=>'Azure регион (оставете празно за глобален ресурс)','Save key'=>'Запазване на ключ','Check my DeepL usage'=>'Проверка на използването на DeepL','%1$s of %2$s characters used this billing period.'=>'Използвани %1$s от %2$s знака през този отчитащ период.','Which engine translates'=>'Кой двигател превежда','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Все още няма настроен двигател. Запазете ключ по-горе (или настройте AI модел), за да започнете превода.','Default engine'=>'Подyразбиращ се двигател','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Двигател за отделен език, автоматичният резервен вариант и месечните ограничения на разходите са функции на Tranzly Pro.','Engine for %s'=>'Двигател за %s','The default engine'=>'По подразбиране двигател','If an engine fails or reaches a limit, try these next, in this order'=>'Ако даден двигател откаже или достигне лимит, опитайте следните стъпки в този ред','Monthly spending caps'=>'Месечни лимити на разходите','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Когато даден двигател достигне лимита си, към него не се изпраща нищо повече до следващия месец, а отчетът за неуспешните преводи посочва причината. Оставете празно за липса на лимит.','%1$s (spent this month: $%2$s)'=>'%1$s (похарчени този месец: $%2$s)','Save caps'=>'Запазване на главни букви','Glossary and words never translated'=>'Речник и думи, които никога не се превеждат','Never translate these words (one per line)'=>'Никога не превеждайте тези думи (по една на ред)','Brand and product names stay exactly as they are, with every engine.'=>'Имената на марките и продуктите остават абсолютно същите при всеки двигател.','Preferred translations and tone per language are Tranzly Pro features.'=>'Предпочитаните преводи и тон за всяка езикова версия са функции на Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Предпочитани преводи (по един на ред: термин = превод)','Formality'=>'Формалност','Default'=>'По подразбиране','Formal'=>'Официален','Informal'=>'Неформално','Style instructions (audience, brand voice)'=>'Стилни инструкции (аудитория, глас на марката)','Save glossary'=>'Запази речника','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Задачите започнаха с %d превода за извършване. Процесът работи във фонов режим: можете да затворите тази страница.','Queued again.'=>'Поставен отново в опашката.','Running'=>'Работещ','Finished'=>'Завършено','Cancelled'=>'Анулиран','Translate in the background'=>'Превеждане във фонов режим','Set up a translation engine in the Engines tab first.'=>'Първо настройте преводачески двигател в раздела „Двигатели“.','Translate every'=>'Преведете всеки','Into'=>'Във','With'=>'С','Each language’s own engine'=>'Собственият двигател на всеки език','Publish the translations (otherwise they are saved as drafts)'=>'Публикувайте преводите (в противен случай те се запазват като чернови)','Estimate the cost'=>'Изчисли разхода','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d публикации, %2$s знака. Цената за този двигател не е известна предварително.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d публикации, %2$s знака: около $%3$s във вашия собствен акаунт.','Start translating'=>'Започнете превода','Jobs'=>'Задачи','No translation jobs yet.'=>'Все още няма задачи за превод.','Job %1$d — %2$s'=>'Задание %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d от %2$d преведени, %3$d неуспешни, %4$d пропуснати (защитени или вече на този език)','Stop this job'=>'Спрете тази задача','See what failed and why'=>'Вижте какво се обърка и защо','Content'=>'Съдържание','Language'=>'Език','What went wrong'=>'Какво се обърка','Fix it'=>'Поправете го','Details'=>'Детайли','Retry with'=>'Повтори с','The same engine'=>'Същият двигател','Retry'=>'Повторен опит','Translate by hand'=>'Превод на ръка','Languages and settings'=>'Езици и настройки','Engines'=>'Двигатели','Translation jobs'=>'Задачи за превод','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Добавете втори език в Tranzly в административното меню и тук ще се появи превключвателят.','Switcher'=>'Превключвател','Accessible label'=>'Достъпен етикет','block titleLanguage switcher'=>'Превключвател на езика','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Връзки към тази страница на всеки от езиците на сайта. Не визуализира нищо, докато не бъдат изброени два или повече езика.','block keywordlanguage'=>'Език','block keywordswitcher'=>'превключвател','block keywordtranslation'=>'превод']];